import tilelang
import tilelang.language as T
import torch
_THRESHOLDS = {'gemm_fp16': 0.1, 'gemm_fp32': 0.05, 'reduce': 0.1, 'softmax': 0.01, 'copy': 1e-05, 'transpose': 1e-05, 'elemwise': 0.001, 'pipeline_fp16': 0.1, 'pipeline_fp32': 0.05}
torch.manual_seed(0)

def _finite_compare(C, ref, check_signed_zero=False):
    """Check exceptional values before measuring finite numerical error.

    Reference results are rounded to the declared output storage dtype. Matching
    NaNs are allowed; a NaN/Inf introduced or lost by the kernel is not.
    """
    import torch
    if C.shape != ref.shape:
        raise RuntimeError(f"WRONG RESULT: shape {tuple(C.shape)} != {tuple(ref.shape)}")
    # Bound temporary memory for the very large shapes generated by the fuzzer.
    # Float64 differences avoid overflowing while subtracting finite fp32 values.
    actual = C.reshape(-1)
    expected = ref.reshape(-1)
    max_error = torch.zeros((), dtype=torch.float64, device=C.device)
    magnitude_sum = torch.zeros_like(max_error)
    finite_count = torch.zeros((), dtype=torch.int64, device=C.device)
    for start in range(0, actual.numel(), 1 << 20):
        c = actual[start:start + (1 << 20)].to(torch.float64)
        r = expected[start:start + (1 << 20)].to(dtype=C.dtype, device=C.device).to(torch.float64)
        if not torch.equal(torch.isnan(c), torch.isnan(r)):
            raise RuntimeError("WRONG RESULT: NaN locations differ")
        if not torch.equal(torch.isposinf(c), torch.isposinf(r)) or not torch.equal(torch.isneginf(c), torch.isneginf(r)):
            raise RuntimeError("WRONG RESULT: infinity locations or signs differ")
        if check_signed_zero:
            zeros = (c == 0) & (r == 0)
            if not torch.equal(torch.signbit(c[zeros]), torch.signbit(r[zeros])):
                raise RuntimeError("WRONG RESULT: signed zeros differ")
        mask = torch.isfinite(c) & torch.isfinite(r)
        max_error = torch.maximum(max_error, torch.where(mask, (c - r).abs(), 0.0).max())
        magnitude_sum += torch.where(mask, r.abs(), 0.0).sum()
        finite_count += mask.sum()
    count = finite_count.item()
    if count == 0:
        return 0.0, 1.0, 0.0
    max_diff = max_error.item()
    ref_norm = magnitude_sum.item() / count + 1e-6
    return max_diff, ref_norm, max_diff / ref_norm

def _max_diff(C, ref, check_signed_zero=False):
    return _finite_compare(C, ref, check_signed_zero=check_signed_zero)[0]

def _region_reference(A, B, body, block_m, block_n, output_dtype, functions=()):
    import torch
    m = A.shape[0]
    n = B.shape[1] if body['operations'][0]['kind'] == 'gemm' else A.shape[1]
    pm, pn = (m + block_m - 1) // block_m * block_m, (n + block_n - 1) // block_n * block_n
    by = torch.arange(pm, device=A.device) // block_m
    function_pool = {fn['name']: fn['body'] for fn in functions}
    def padded(x):
        return torch.nn.functional.pad(x, (0, pn - n, 0, pm - m))
    def execute(region, parent, argument=None):
        values = dict(parent)
        if region['arguments']:
            values[region['arguments'][0]] = argument
        for op in region['operations']:
            kind, attrs = op['kind'], op['attrs']
            args = [values[v] for v in op['operands']]
            if kind == 'load':
                result = padded(A.float())
            elif kind == 'gemm':
                result = padded(A.float() @ B.float())
            elif kind == 'call':
                callee = function_pool[attrs['callee']]
                # A callee sees only its own formal arguments, never caller locals.
                bindings = dict(zip(callee['arguments'], args))
                result = execute({**callee, 'arguments': []}, bindings)
            elif kind == 'scale':
                result = args[0] * attrs['alpha']
            elif kind == 'neg':
                result = -args[0]
            elif kind == 'abs':
                result = args[0].abs()
            elif kind == 'sqrt':
                result = args[0].abs().sqrt()
            elif kind == 'round':
                result = args[0].to(getattr(torch, attrs['dtype'])).float()
            elif kind == 'add':
                result = args[0] + args[1]
            elif kind == 'mul':
                result = args[0] * args[1]
            elif kind == 'copy':
                result = args[0].clone()
            elif kind == 'exp':
                result = args[0].clamp(-10, 10).exp()
            elif kind == 'sub':
                result = args[0] - args[1]
            elif kind == 'maximum':
                result = torch.maximum(args[0], args[1])
            elif kind == 'minimum':
                result = torch.minimum(args[0], args[1])
            elif kind == 'div':
                # Defined division avoids trivial zero-denominator failures.
                result = args[0] / args[1].abs().clamp_min(1e-3)
            elif kind == 'where':
                result = torch.where(args[0] > 0, args[1], args[2])
            elif kind == 'tile_transpose':
                result = args[0].reshape(pm//block_m, block_m, pn//block_n, block_n).permute(0, 3, 2, 1).reshape(pm, pn)
            elif kind.startswith('row_'):
                tiles = args[0].reshape(pm, pn//block_n, block_n)
                if kind == 'row_softmax':
                    result = tiles.softmax(-1).reshape(pm, pn)
                else:
                    fn = {'row_sum': 'sum', 'row_max': 'amax', 'row_min': 'amin'}[kind]
                    result = getattr(tiles, fn)(-1, keepdim=True).expand_as(tiles).reshape(pm, pn)
            elif kind == 'for':
                result = args[0]
                for _ in range(attrs['trip_count']):
                    result = execute(op['regions'][0], values, result)
            elif kind == 'if':
                left = execute(op['regions'][0], values, args[0])
                right = execute(op['regions'][1], values, args[0])
                result = torch.where((by % 2 == attrs['parity'])[:, None], left, right)
            else:
                raise ValueError('Unsupported region reference operation: ' + kind)
            values[op['result']] = result
        return values[region['yield_value']]
    return execute(body, {})[:m, :n].to(getattr(torch, output_dtype))

dtype = "float32"
@tilelang.jit
def make_kernel():
    @T.macro
    def fn_0(arg0, by, fn_out):
        v1 = T.alloc_fragment((64, 16), "float32")
        v2 = T.alloc_fragment((64, 16), "float32")
        v2_stat = T.alloc_fragment((64,), "float32")
        v11 = T.alloc_fragment((64, 16), "float32")
        v3 = T.alloc_fragment((64, 16), "float32")
        v10 = T.alloc_fragment((64, 16), "float32")
        v4 = T.alloc_fragment((64, 16), "float32")
        v9 = T.alloc_fragment((64, 16), "float32")
        v5 = T.alloc_fragment((64, 16), "float32")
        v7 = T.alloc_fragment((64, 16), "float32")
        v6 = T.alloc_fragment((64, 16), "float32")
        v8 = T.alloc_fragment((64, 16), "float32")
        for i, j in T.Parallel(64, 16):
            v1[i, j] = arg0[i, j] * 3.653895447771774
        T.reduce_sum(v1, v2_stat, dim=1, clear=True)
        for i, j in T.Parallel(64, 16):
            v2[i, j] = v2_stat[i]
        if by % 2 == 0:
            T.copy(v1, v3)
            for i, j in T.Parallel(64, 16):
                v4[i, j] = T.cast(T.cast(v2[i, j], "float32"), "float32")
            if by % 2 == 0:
                T.copy(v4, v5)
                for i, j in T.Parallel(64, 16):
                    v6[i, j] = v4[i, j] * v2[i, j]
                T.copy(v6, v9)
            else:
                T.copy(v4, v7)
                for i, j in T.Parallel(64, 16):
                    v8[i, j] = T.min(v7[i, j], v2[i, j])
                T.copy(v8, v9)
            T.copy(v9, v11)
        else:
            T.copy(v1, v10)
            T.copy(v10, v11)
        T.copy(v11, fn_out)
    @T.macro
    def fn_1(arg0, by, fn_out):
        v1 = T.alloc_fragment((64, 16), "float32")
        v10 = T.alloc_fragment((64, 16), "float32")
        v2 = T.alloc_fragment((64, 16), "float32")
        v9 = T.alloc_fragment((64, 16), "float32")
        v8 = T.alloc_fragment((64, 16), "float32")
        v3 = T.alloc_fragment((64, 16), "float32")
        v4 = T.alloc_fragment((64, 16), "float32")
        v5 = T.alloc_fragment((64, 16), "float32")
        v6 = T.alloc_fragment((64, 16), "float32")
        v7 = T.alloc_fragment((64, 16), "float32")
        v11 = T.alloc_fragment((64, 16), "float32")
        for i, j in T.Parallel(64, 16):
            v1[i, j] = T.cast(T.cast(arg0[i, j], "float32"), "float32")
        if by % 2 == 1:
            T.copy(v1, v2)
            T.copy(v1, v8)
            for iter_v8 in T.serial(1):
                T.copy(v8, v3)
                for i, j in T.Parallel(64, 16):
                    v4[i, j] = T.if_then_else(v1[i, j] > 0, arg0[i, j], v2[i, j])
                fn_0(v2, by, v5)
                for i, j in T.Parallel(64, 16):
                    v6[i, j] = T.max(v2[i, j], arg0[i, j])
                for i, j in T.Parallel(64, 16):
                    v7[i, j] = v2[i, j] * 1.5333824857460274
                T.copy(v7, v8)
            T.copy(v8, v10)
        else:
            T.copy(v1, v9)
            T.copy(v9, v10)
        fn_0(v10, by, v11)
        T.copy(v11, fn_out)
    @T.prim_func
    def impl(A: T.Buffer((4, 4), dtype), B: T.Buffer((1, 4), dtype), C: T.Buffer((4, 4), dtype)):
        with T.Kernel(1, 1, threads=256) as (by, bx):
            v1 = T.alloc_fragment((64, 16), "float32")
            v2 = T.alloc_fragment((64, 16), "float32")
            v3 = T.alloc_fragment((64, 16), "float32")
            v8 = T.alloc_fragment((64, 16), "float32")
            v4 = T.alloc_fragment((64, 16), "float32")
            v5 = T.alloc_fragment((64, 16), "float32")
            v5_stat = T.alloc_fragment((64,), "float32")
            v6 = T.alloc_fragment((64, 16), "float32")
            v7 = T.alloc_fragment((64, 16), "float32")
            v9 = T.alloc_fragment((64, 16), "float32")
            v10 = T.alloc_fragment((64, 16), "float32")
            for i, j in T.Parallel(64, 16):
                v1[i, j] = T.if_then_else(by * 64 + i < 4 and bx * 16 + j < 4, T.cast(A[by * 64 + i, bx * 16 + j], "float32"), T.float32(0))
            for i, j in T.Parallel(64, 16):
                v2[i, j] = v1[i, j] * 8.75239180752028
            for i, j in T.Parallel(64, 16):
                v3[i, j] = v2[i, j] * v1[i, j]
            T.copy(v1, v8)
            for iter_v8 in T.serial(3):
                T.copy(v8, v4)
                T.reduce_max(v3, v5_stat, dim=1, clear=True)
                for i, j in T.Parallel(64, 16):
                    v5[i, j] = T.exp(v3[i, j] - v5_stat[i])
                T.reduce_sum(v5, v5_stat, dim=1, clear=True)
                for i, j in T.Parallel(64, 16):
                    v5[i, j] = v5[i, j] / v5_stat[i]
                for i, j in T.Parallel(64, 16):
                    v6[i, j] = T.abs(v3[i, j])
                for i, j in T.Parallel(64, 16):
                    v7[i, j] = T.sqrt(T.abs(v6[i, j]))
                T.copy(v7, v8)
            fn_1(v8, by, v9)
            fn_1(v9, by, v10)
            T.copy(v10, C[by * 64, bx * 16])
    return impl

def test_kernel_0():
    torch.manual_seed(0)
    A = torch.randn((4, 4), device='cuda', dtype=torch.float32) * 0.1
    B = torch.randn((1, 4), device='cuda', dtype=torch.float32) * 0.1
    C = torch.empty((4, 4), device='cuda', dtype=torch.float32)
    compiled = make_kernel()
    compiled(A, B, C)
    torch.cuda.synchronize()
    ref = _region_reference(A, B, {'arguments': [], 'operations': [{'kind': 'load', 'result': 'v1', 'operands': [], 'attrs': {}, 'regions': []}, {'kind': 'scale', 'result': 'v2', 'operands': ['v1'], 'attrs': {'alpha': 8.75239180752028}, 'regions': []}, {'kind': 'mul', 'result': 'v3', 'operands': ['v2', 'v1'], 'attrs': {}, 'regions': []}, {'kind': 'for', 'result': 'v8', 'operands': ['v1'], 'attrs': {'trip_count': 3}, 'regions': [{'arguments': ['v4'], 'operations': [{'kind': 'row_softmax', 'result': 'v5', 'operands': ['v3'], 'attrs': {}, 'regions': []}, {'kind': 'abs', 'result': 'v6', 'operands': ['v3'], 'attrs': {}, 'regions': []}, {'kind': 'sqrt', 'result': 'v7', 'operands': ['v6'], 'attrs': {}, 'regions': []}], 'yield_value': 'v7'}]}, {'kind': 'call', 'result': 'v9', 'operands': ['v8'], 'attrs': {'callee': 'fn_1'}, 'regions': []}, {'kind': 'call', 'result': 'v10', 'operands': ['v9'], 'attrs': {'callee': 'fn_1'}, 'regions': []}], 'yield_value': 'v10'}, 64, 16, 'float32', [{'name': 'fn_0', 'body': {'arguments': ['arg0'], 'operations': [{'kind': 'scale', 'result': 'v1', 'operands': ['arg0'], 'attrs': {'alpha': 3.653895447771774}, 'regions': []}, {'kind': 'row_sum', 'result': 'v2', 'operands': ['v1'], 'attrs': {}, 'regions': []}, {'kind': 'if', 'result': 'v11', 'operands': ['v1'], 'attrs': {'parity': 0}, 'regions': [{'arguments': ['v3'], 'operations': [{'kind': 'round', 'result': 'v4', 'operands': ['v2'], 'attrs': {'dtype': 'float32'}, 'regions': []}, {'kind': 'if', 'result': 'v9', 'operands': ['v4'], 'attrs': {'parity': 0}, 'regions': [{'arguments': ['v5'], 'operations': [{'kind': 'mul', 'result': 'v6', 'operands': ['v4', 'v2'], 'attrs': {}, 'regions': []}], 'yield_value': 'v6'}, {'arguments': ['v7'], 'operations': [{'kind': 'minimum', 'result': 'v8', 'operands': ['v7', 'v2'], 'attrs': {}, 'regions': []}], 'yield_value': 'v8'}]}], 'yield_value': 'v9'}, {'arguments': ['v10'], 'operations': [], 'yield_value': 'v10'}]}], 'yield_value': 'v11'}}, {'name': 'fn_1', 'body': {'arguments': ['arg0'], 'operations': [{'kind': 'round', 'result': 'v1', 'operands': ['arg0'], 'attrs': {'dtype': 'float32'}, 'regions': []}, {'kind': 'if', 'result': 'v10', 'operands': ['v1'], 'attrs': {'parity': 1}, 'regions': [{'arguments': ['v2'], 'operations': [{'kind': 'for', 'result': 'v8', 'operands': ['v1'], 'attrs': {'trip_count': 1}, 'regions': [{'arguments': ['v3'], 'operations': [{'kind': 'where', 'result': 'v4', 'operands': ['v1', 'arg0', 'v2'], 'attrs': {}, 'regions': []}, {'kind': 'call', 'result': 'v5', 'operands': ['v2'], 'attrs': {'callee': 'fn_0'}, 'regions': []}, {'kind': 'maximum', 'result': 'v6', 'operands': ['v2', 'arg0'], 'attrs': {}, 'regions': []}, {'kind': 'scale', 'result': 'v7', 'operands': ['v2'], 'attrs': {'alpha': 1.5333824857460274}, 'regions': []}], 'yield_value': 'v7'}]}], 'yield_value': 'v8'}, {'arguments': ['v9'], 'operations': [], 'yield_value': 'v9'}]}, {'kind': 'call', 'result': 'v11', 'operands': ['v10'], 'attrs': {'callee': 'fn_0'}, 'regions': []}], 'yield_value': 'v11'}}])
    max_diff, _, relative_error = _finite_compare(C, ref)
    error = relative_error if False else max_diff
    tolerance = 0.05 if False else 0.001
    if error > tolerance:
        raise RuntimeError(f'WRONG RESULT: structured reference error={error}')


import json as _json
_original_finite = _finite_compare
def _observed_finite(actual, expected, *args, **kwargs):
    a, b = actual.detach().float(), expected.detach().float()
    delta = (a-b).abs()
    finite = torch.isfinite(delta)
    coords = torch.nonzero(finite & (delta > 0))[:8]
    record = {'shape': list(a.shape), 'a_max': a.abs().max().item(), 'b_max': b.abs().max().item(),
              'a_mean': a.abs().mean().item(), 'b_mean': b.abs().mean().item(),
              'maxdiff': delta[finite].max().item() if finite.any() else None,
              'differences': int((a != b).sum()),
              'samples': [(c.tolist(), a[tuple(c)].item(), b[tuple(c)].item()) for c in coords]}
    print('NUMERIC', _json.dumps(record), flush=True)
    return _original_finite(actual, expected, *args, **kwargs)
_finite_compare = _observed_finite
if '_region_check' in globals():
    _original_check = _region_check
    def _region_check(actual, expected, relative, tolerance, label):
        print('CHECK', label, flush=True)
        try: return _original_check(actual, expected, relative, tolerance, label)
        except RuntimeError as e: print('OBSERVED_FAILURE', str(e), flush=True)
if '_region_equal' in globals():
    _original_equal = _region_equal
    def _region_equal(actual, expected, label):
        try: return _original_equal(actual, expected, label)
        except RuntimeError as e:
            print('EXACT_FAILURE', label, flush=True)
            _observed_finite(actual, expected)

